#!/usr/bin/env bash
# Generated by gq (@getquick/site) from gq.ops.json; gq sync rewrites it.
# The plugins it activates are gq.ops.json's wordpress.plugins, the
# language it installs and activates is wordpress.locale, and the languages
# it installs and gives Polylang beside it are wordpress.languages.
# Site-specific deploy steps go in deploy/ploi/admin.d (see its README.md).
set -euo pipefail

APP_PATH="apps/cms"
# gq.ops.json's wordpress.locale; empty leaves the site's language as it is.
WP_LOCALE="{{wordpress.locale}}"
# gq.ops.json's wordpress.languages, as locale:slug pairs; empty for a
# monolingual Site, which leaves Polylang alone.
WP_LANGUAGES="{{wordpress.languages}}"
# gq.ops.json's variant: a commerce Site also updates WooCommerce's database.
SITE_VARIANT="{{variant}}"
# gq.ops.json's deployment.guardedPackages: Composer packages whose installed
# files must match the release's PACKAGE_EXPECTATIONS (which `gq ploi release`
# writes once it has checked them) before PHP-FPM reloads or WordPress runs.
# Empty for a Site that guards none.
GUARDED_PACKAGES="{{deployment.guardedPackages}}"
SITE_PATH="${PLOI_SITE_PATH:-$PWD}"
# The site has no git repository (Ploi custom deployments): `pnpm ploi:release`
# uploads a release archive to R2 and passes a short-lived URL as the deploy
# variable archive_url, which Ploi exposes as ARCHIVE_URL.
ARCHIVE_URL="${ARCHIVE_URL:-}"
# Composer installs the GETQUICK plugins from the private registry
# (proxy.composer.getquick.io); `pnpm ploi:release` passes the login as the
# deploy variable composer_auth. Never echo it.
export COMPOSER_AUTH="${COMPOSER_AUTH:-}"
SHIPPED_PATHS=("$APP_PATH" deploy/ploi)
# The site's own deploy steps, shipped with deploy/ploi.
EXTENSIONS_PATH="deploy/ploi/admin.d"
maintenance_enabled=false
tmp_dir=""

cd "$SITE_PATH"

reload_php_fpm() {
  if ! command -v sudo >/dev/null 2>&1 || ! command -v php >/dev/null 2>&1; then
    echo "Skipping PHP-FPM reload; sudo or PHP is unavailable."
    return 0
  fi

  php_fpm_service="php$(php -r 'echo PHP_MAJOR_VERSION . "." . PHP_MINOR_VERSION;')-fpm"
  if sudo -n service "$php_fpm_service" reload; then
    echo "Reloaded $php_fpm_service to clear PHP opcache."
  else
    echo "Could not reload $php_fpm_service; PHP workers may retain stale opcache." >&2
  fi
}

# Runs from $APP_PATH. Composer deletes the install directory of a package
# that left composer.lock, even when the release now ships that directory
# itself (a plugin moved from the registry into the site's repository), so
# every plugin and theme the release ships is copied back afterwards. This is
# also what removes files a shipped plugin or theme no longer has: the main
# rsync protects those directories.
composer_install() {
  composer install --no-dev --prefer-dist --optimize-autoloader --no-interaction
  for kind in plugins themes; do
    for shipped_dir in "$tmp_dir/release/$APP_PATH/web/app/$kind"/*/; do
      [ -d "$shipped_dir" ] || continue
      rsync -a --delete "$shipped_dir" "web/app/$kind/$(basename "$shipped_dir")/"
    done
  done
  # Verify after restoring shipped plugins too. Runs in full and Composer-only
  # deployments, before PHP reload or any WordPress activation/database work.
  # The patched dependency (wpgraphql-blocks) is content-only.
  if [ "$SITE_VARIANT" != commerce ]; then
    php scripts/patch-dependencies.php
  fi
  verify_package_expectations
}

# Runs from $APP_PATH after composer install: each package the release's
# PACKAGE_EXPECTATIONS states must be installed with exactly its files (the
# gq-tree-v1 listing: regular files only, `sha256sum` lines sorted by path
# bytes, whose sha256 is the package's digest), from the very composer.lock
# gq checked. Any difference fails the deploy before PHP-FPM reloads and
# before any WP-CLI activation or database step. A release without the file
# is fine unless the Site guards packages.
verify_package_expectations() {
  local expectations="$tmp_dir/release/PACKAGE_EXPECTATIONS"
  local line key package_line lock="" name="" count=0 verified=" " guarded
  if [ ! -f "$expectations" ]; then
    if [ -n "$GUARDED_PACKAGES" ]; then
      echo "This Site guards $GUARDED_PACKAGES, but the release has no PACKAGE_EXPECTATIONS: deploy it with gq ploi release." >&2
      exit 1
    fi
    return 0
  fi
  if [ "$(head -n 1 "$expectations")" != "gq-package-expectations 1" ]; then
    echo "PACKAGE_EXPECTATIONS isn't a version 1 expectations file." >&2
    exit 1
  fi
  # Whole lines: a file's path is everything after its hash, spaces and all.
  while IFS= read -r line; do
    key="${line%% *}"
    case "$key" in
      gq-package-expectations) ;;
      lock) lock="${line#lock }" ;;
      package)
        [ -z "$name" ] || verify_package_tree "$name" "$count"
        count=$((count + 1))
        # name, version, install path and digest, one per line
        package_line="${line#package }"
        printf '%s\n' $package_line >"$tmp_dir/package-$count"
        name="${package_line%% *}"
        : >"$tmp_dir/expected-$count"
        ;;
      file) printf '%s  %s\n' "${line:5:64}" "${line:70}" >>"$tmp_dir/expected-$count" ;;
      *)
        echo "PACKAGE_EXPECTATIONS has an unknown line: $key" >&2
        exit 1
        ;;
    esac
  done <"$expectations"
  [ -z "$name" ] || verify_package_tree "$name" "$count"
  if [ -z "$lock" ] || [ "$(sha256sum composer.lock | cut -c1-64)" != "$lock" ]; then
    echo "composer.lock isn't the lock gq checked before uploading this release." >&2
    exit 1
  fi
  for guarded in $GUARDED_PACKAGES; do
    if [[ "$verified" != *" $guarded "* ]]; then
      echo "This Site guards $guarded, but PACKAGE_EXPECTATIONS doesn't state it." >&2
      exit 1
    fi
  done
}

# verify_package_tree <name> <n>: the package's installed files against
# $tmp_dir/expected-<n>, its version, path and digest in $tmp_dir/package-<n>.
verify_package_tree() {
  local name="$1" n="$2" version install_path digest actual="$tmp_dir/actual-$2"
  { read -r _; read -r version; read -r install_path; read -r digest; } <"$tmp_dir/package-$n"
  if [ ! -d "$install_path" ]; then
    echo "$name isn't installed at $APP_PATH/$install_path." >&2
    exit 1
  fi
  if [ -n "$(find "$install_path" ! -type f ! -type d -print -quit)" ]; then
    echo "$name's $install_path holds something other than regular files and directories." >&2
    exit 1
  fi
  (cd "$install_path" && find . -type f -print0 | LC_ALL=C sort -z | xargs -0 -r sha256sum) \
    | sed 's#^\([0-9a-f]\{64\}\)  \./#\1  #' >"$actual"
  if grep -qv '^[0-9a-f]\{64\}  ' "$actual" || ! cmp -s "$tmp_dir/expected-$n" "$actual" \
    || [ "$(sha256sum <"$actual" | cut -c1-64)" != "$digest" ]; then
    echo "$name's installed files don't match its expected $version tree ($digest):" >&2
    awk 'NR == FNR { want[substr($0, 67)] = substr($0, 1, 64); next }
      { have[substr($0, 67)] = substr($0, 1, 64) }
      END {
        for (path in want) {
          if (!(path in have)) print "  missing " path
          else if (want[path] != have[path]) print "  changed " path
        }
        for (path in have) if (!(path in want)) print "  extra   " path
      }' "$tmp_dir/expected-$n" "$actual" | LC_ALL=C sort >&2
    exit 1
  fi
  echo "Verified $name $version: $(wc -l <"$actual" | tr -d ' ') files match $digest."
  verified+="$name "
}

cleanup() {
  exit_code=$?
  trap - EXIT

  if [ "$maintenance_enabled" = true ] && [ -f "$SITE_PATH/$APP_PATH/web/wp/wp-load.php" ]; then
    (cd "$SITE_PATH/$APP_PATH" && wp maintenance-mode deactivate) || true
  fi

  if [ -n "$tmp_dir" ] && [ -d "$tmp_dir" ]; then
    rm -rf "$tmp_dir"
  fi

  deployed_sha="$(sed -n 's/^commit=//p' "$SITE_PATH/RELEASE" 2>/dev/null | head -1)"
  deployed_sha="${deployed_sha:-unknown}"
  if [ "$exit_code" -eq 0 ]; then
    echo "{{deployStatusMarker}}=success SHA=$deployed_sha"
  else
    echo "{{deployStatusMarker}}=failed EXIT_CODE=$exit_code SHA=$deployed_sha"
  fi

  exit "$exit_code"
}

trap cleanup EXIT

if [ -z "$ARCHIVE_URL" ]; then
  echo "ARCHIVE_URL is not set. Deploy with \`pnpm ploi:release\`, which uploads the release to R2 and passes its URL." >&2
  exit 1
fi

if [ -z "$COMPOSER_AUTH" ]; then
  echo "COMPOSER_AUTH is not set. Deploy with \`pnpm ploi:release\` (or CI), which passes the registry login." >&2
  exit 1
fi

tmp_dir="$(mktemp -d)"
curl -fsSL --retry 3 -o "$tmp_dir/release.tar.gz" "$ARCHIVE_URL"
mkdir "$tmp_dir/release"
tar -xzf "$tmp_dir/release.tar.gz" -C "$tmp_dir/release"
if [ ! -f "$tmp_dir/release/RELEASE" ] || [ ! -f "$tmp_dir/release/$APP_PATH/composer.json" ]; then
  echo "The release archive has no RELEASE manifest or $APP_PATH/composer.json." >&2
  exit 1
fi
echo "Deploying $(tr '\n' ' ' < "$tmp_dir/release/RELEASE")"

# Replace the shipped code, keeping what the server owns: the .env, Composer's
# vendor/ and installed WordPress core/plugins/themes, language packs and
# uploads.
for path in "${SHIPPED_PATHS[@]}"; do
  mkdir -p "$path"
  rsync -a --delete \
    --filter='P /.env' \
    --filter='P /vendor/' \
    --filter='P /web/wp/' \
    --filter='P /web/app/languages/' \
    --filter='P /web/app/uploads/' \
    --filter='P /web/app/plugins/*/' \
    --filter='P /web/app/themes/*/' \
    --filter='P /web/app/mu-plugins/*/' \
    "$tmp_dir/release/$path/" "$path/"
done
cp "$tmp_dir/release/RELEASE" RELEASE

# Ploi's environment editor manages the site-root .env; Bedrock reads it from
# the app directory.
if [ -f .env ]; then
  cp .env "$APP_PATH/.env"
fi

# Ploi can leave its placeholder in the site root. Remove it so the configured
# Bedrock docroot serves apps/cms/web/index.php.
if [ -f index.html ]; then
  rm -f index.html
fi

# If an existing Ploi site still uses the default /public web directory, point
# that directory at the Bedrock web root so Nginx can reach WordPress.
if [ -L public ]; then
  current_public_target="$(readlink public)"
  if [ "$current_public_target" != "$APP_PATH/web" ]; then
    rm -f public
    ln -s "$APP_PATH/web" public
  fi
elif [ ! -e public ]; then
  ln -s "$APP_PATH/web" public
elif [ -d public ] && [ -f public/index.html ] && [ "$(find public -mindepth 1 -maxdepth 1 | wc -l)" -eq 1 ]; then
  rm -rf public
  ln -s "$APP_PATH/web" public
elif [ -d public ]; then
  echo "Leaving existing public/ directory in place. Set Ploi's web directory to $APP_PATH/web or replace public/ with a symlink to $APP_PATH/web."
else
  echo "public exists and is not a directory or symlink. Set Ploi's web directory to $APP_PATH/web."
fi

# A Composer-only deployment updates tracked WordPress/plugin files and vendor
# packages, then exits before any WP-CLI or database operation.
if [ "${COMPOSER_ONLY:-false}" = "true" ]; then
  cd "$APP_PATH"
  composer_install
  mkdir -p web/app/uploads
  reload_php_fpm
  echo "Composer dependencies deployed; skipping WordPress and database operations."
  exit 0
fi

if [ -f "$APP_PATH/web/wp/wp-load.php" ] && (cd "$APP_PATH" && wp core is-installed); then
  (cd "$APP_PATH" && wp maintenance-mode activate) || true
  maintenance_enabled=true
fi

cd "$APP_PATH"
composer_install

# Uploads are runtime content, not repository code. Keep the directory present
# on a fresh site and configure it as persistent storage before publishing media.
mkdir -p web/app/uploads

reload_php_fpm

if [ ! -f web/index.php ]; then
  echo "Expected Bedrock web/index.php after composer install."
  exit 1
fi

# The first deployment only installs the Bedrock files. WordPress is installed
# from /wp/wp-admin/install.php once the production database exists; every
# deploy after that activates plugins/theme and applies pending migrations.
require_installed() {
  if ! wp "$1" is-installed "$2"; then
    echo "Expected $1 $2 to be installed by Composer in $APP_PATH." >&2
    exit 1
  fi
}

# Installs WP_LOCALE's core language pack (en_US ships with WordPress) and
# makes it the site's language, then installs and updates the translations
# WordPress.org has for the installed plugins and themes. Production disallows
# file modifications, so the admin can't install a language; WP-CLI can. A
# core pack that can't be installed fails the deploy; a missing plugin or
# theme translation (the GETQUICK plugins have none) only warns.
apply_locale() {
  [ -n "$WP_LOCALE" ] || return 0
  if [ "$WP_LOCALE" = en_US ]; then
    wp option update WPLANG "" --quiet
    return 0
  fi
  install_core_language "$WP_LOCALE"
  wp option update WPLANG "$WP_LOCALE" --quiet
  wp language core update --quiet || echo "Could not update the $WP_LOCALE core translations." >&2
  for kind in plugin theme; do
    wp language "$kind" install --all "$WP_LOCALE" --quiet \
      || echo "Some $kind translations for $WP_LOCALE are not available." >&2
    wp language "$kind" update --all --quiet \
      || echo "Could not update the $kind translations for $WP_LOCALE." >&2
  done
}

# Installs a locale's core language pack unless it is (en_US ships with
# WordPress).
install_core_language() {
  [ "$1" != en_US ] || return 0
  if ! wp language core is-installed "$1"; then
    wp language core install "$1"
  fi
}

# Installs the core language pack of each of WP_LANGUAGES, then makes
# Polylang's languages match WP_LOCALE and WP_LANGUAGES (deploy/ploi/polylang.sh,
# which stops the deploy rather than delete a language that has content).
apply_languages() {
  local language
  [ -n "$WP_LANGUAGES" ] || return 0
  for language in $WP_LANGUAGES; do
    install_core_language "${language%%:*}"
  done
  # shellcheck disable=SC2086 # one argument per language
  bash "$SITE_PATH/deploy/ploi/polylang.sh" "$WP_LOCALE" $WP_LANGUAGES
}

# Runs each deploy extension ($EXTENSIONS_PATH/*.sh, site-owned) with bash
# from $APP_PATH, in lexical (byte) order, with SITE_PATH and APP_PATH set:
# after activation and the database update, before the rewrite flush.
# The first one that exits non-zero fails the deploy with its exit code. No
# directory, or no extension in it, is fine.
run_deploy_extensions() {
  local extension extension_status
  [ -d "$SITE_PATH/$EXTENSIONS_PATH" ] || return 0
  find "$SITE_PATH/$EXTENSIONS_PATH" -mindepth 1 -maxdepth 1 -type f -name '*.sh' \
    | LC_ALL=C sort >"$tmp_dir/extensions"
  while IFS= read -r extension; do
    echo "Running deploy extension ${extension#"$SITE_PATH/"}"
    extension_status=0
    SITE_PATH="$SITE_PATH" APP_PATH="$APP_PATH" bash "$extension" </dev/null || extension_status=$?
    if [ "$extension_status" -ne 0 ]; then
      echo "Deploy extension ${extension#"$SITE_PATH/"} failed (exit $extension_status)." >&2
      exit "$extension_status"
    fi
  done <"$tmp_dir/extensions"
}

if wp core is-installed; then
  # The GETQUICK theme (or the site's child of it) must stay installed.
  require_installed theme getquick-theme
  # gq.ops.json's wordpress.plugins: Composer installing a plugin doesn't
  # activate it.
  for plugin in {{wordpress.plugins}}; do
    require_installed plugin "$plugin"
    wp plugin activate "$plugin" --quiet
  done
  # gq-config is a must-use plugin (always active, invisible to
  # `wp plugin`); check that Bedrock's autoloader actually loaded it.
  if ! wp eval 'exit(defined("GETQUICK_CONFIG_VERSION") ? 0 : 1);'; then
    echo "The gq-config must-use plugin did not load (GETQUICK_CONFIG_VERSION is undefined)." >&2
    exit 1
  fi
  wp core update-db --quiet
  # WooCommerce's own database update, after its plugin is active. It only
  # goes forward: a release that changes WooCommerce's database version says
  # whether the release before it still runs on it (rollback-safe or not).
  if [ "$SITE_VARIANT" = commerce ]; then
    wp wc update
  fi
  apply_locale
  apply_languages
  run_deploy_extensions
  wp rewrite flush --hard --quiet

  # Media on R2: the first deploy with S3 Uploads configured copies the
  # uploads already on the server into the bucket, once.
  if wp eval 'exit(defined("S3_UPLOADS_BUCKET") && S3_Uploads\enabled() ? 0 : 1);' 2>/dev/null \
    && ! wp option get getquick_media_uploads_copied >/dev/null 2>&1; then
    echo "Copying existing uploads to the R2 media bucket…"
    wp s3-uploads upload-directory web/app/uploads uploads
    wp option add getquick_media_uploads_copied "$(date -u +%Y-%m-%dT%H:%M:%SZ)" --autoload=no
  fi
fi

wp maintenance-mode deactivate || true
maintenance_enabled=false
